      "predictions": [
        {
          "entity_id": "service:gridcast:feature-service",
          "key": "sql_statements_per_build",
          "operator": "gt",
          "value": 1000
        },
        {
          "entity_id": "service:gridcast:feature-service",
          "key": "build_p95_seconds",
          "operator": "gt",
          "value": 5.0
        },
        {
          "entity_id": "service:gridcast:postgres",
          "key": "rows_scanned_per_s",
          "operator": "gt",
          "value": 10000
        },
        {
          "entity_id": "service:gridcast:forecast-pipeline",
          "key": "slow_trace_duration_ms",
          "operator": "gt",
          "value": 5000
        }
